def load() -> pd.DataFrame:
    import pandas as pd, glob, os
    pattern = 'data/legal/input/csn-data-book-2024-csv/CSVs/State MSA Identity Theft data/*'
    files = sorted(glob.glob(pattern))
    if not files:
        raise FileNotFoundError(f'No files matched: {pattern}')

    dfs = []
    for fp in files:
        # try common encodings
        for enc in ['utf-8', 'latin-1', 'cp1252']:
            try:
                df = pd.read_csv(fp, dtype=str, encoding=enc)
                break
            except Exception:
                df = None
        if df is None:
            df = pd.read_csv(fp, dtype=str, encoding_errors='ignore')
        df.columns = [str(c).strip() for c in df.columns]
        df['__source_file'] = os.path.basename(fp)
        dfs.append(df)
    return pd.concat(dfs, ignore_index=True, sort=False)

def process(msaIdTheftRaw) -> pd.DataFrame:
    import pandas as pd

    df = msaIdTheftRaw.copy()

    # show per-file shapes and a sample of the first non-null rows to understand header structure
    files = sorted(df['__source_file'].unique().tolist())
    out_rows = []
    for f in files[:10]:
        d = df[df['__source_file'] == f].copy()
        out_rows.append({
            '__source_file': f,
            'rows': len(d),
            'nonNullAreaRows': int(d['Metropolitan Areas: Identity Theft Reports'].notna().sum()),
            'nonNullValRows': int(d['Unnamed: 1'].notna().sum()),
            'uniqueAreaFirst10': '; '.join(d['Metropolitan Areas: Identity Theft Reports'].dropna().astype(str).head(5).tolist()),
            'uniqueValFirst10': '; '.join(d['Unnamed: 1'].dropna().astype(str).head(5).tolist()),
        })

    # also show raw column names
    meta = pd.DataFrame([{
        'columns': ', '.join(df.columns.tolist()),
        'n_files': len(files),
        'total_rows': len(df)
    }])

    return pd.concat([meta, pd.DataFrame(out_rows)], ignore_index=True)
